"""Fixtures shared between integration and e2e Drizzle tests."""

from __future__ import annotations

import hashlib
import textwrap
from dataclasses import dataclass

import pytest

from iris_pgwire.config import DDLTranslationConfig
from iris_pgwire.migrations.executor import MigrationExecutor
from iris_pgwire.sql_translator.ddl_translator import DDLTranslator


@dataclass(frozen=True)
class DrizzleMigrationFile:
    """Represents a Drizzle-style migration file encountered in production."""

    filename: str
    statements: tuple[str, ...]
    content: str
    hash: str
    target_table: str | None = None

    @classmethod
    def _normalize(cls, sql: str) -> str:
        return textwrap.dedent(sql).strip()

    @classmethod
    def from_sql(
        cls, filename: str, sql: str, target_table: str | None = None
    ) -> "DrizzleMigrationFile":
        normalized = cls._normalize(sql)
        return cls(
            filename=filename,
            statements=(normalized,),
            content=normalized,
            hash=hashlib.sha256(normalized.encode("utf-8")).hexdigest(),
            target_table=target_table,
        )

    @classmethod
    def from_statements(
        cls, filename: str, statements: tuple[str, ...], target_table: str | None = None
    ) -> "DrizzleMigrationFile":
        normalized = tuple(cls._normalize(stmt) for stmt in statements)
        combined = "\n\n".join(normalized)
        return cls(
            filename=filename,
            statements=normalized,
            content=combined,
            hash=hashlib.sha256(combined.encode("utf-8")).hexdigest(),
            target_table=target_table,
        )


