@pytest.fixture
def drizzle_failure_migration_file() -> DrizzleMigrationFile:
    """Migration that contains an intentional syntax error to force rollback."""
    return DrizzleMigrationFile.from_statements(
        "0006_failure_example.sql",
        (
            """
            -- Drizzle migration (0006_failure_example.sql)
            CREATE TABLE "rollback_failure_demo" (
                "id" uuid PRIMARY KEY NOT NULL
            );
            """,
            """
            -- The next statement is intentionally malformed.
            CREATE TAABLE "broken_statement" ("id" text);
            """,
            """
            -- This never runs, but Drizzle would emit a third table.
            CREATE TABLE "should_not_exist" (
                "id" text PRIMARY KEY NOT NULL
            );
            """,
        ),
        target_table="rollback_failure_demo",
    )
